def verify(o):
 if isinstance(o,dict):
  if 'path' in o and 'sha256' in o:assert bind(o['path'])['sha256']==o['sha256'],o['path']
  for v in o.values():verify(v)
 elif isinstance(o,list):
  for v in o:verify(v)
